(()=>{'use strict';
const E=x=>(window.esc?esc(x):String(x??'')),D=x=>(window.dateBR?dateBR(x):x),today=()=>new Date().toISOString().slice(0,10);
function visits(){if(currentTab!=='Presidência'||document.querySelector('.sv6Visits'))return;const ms=Array.isArray(state.meetings)?state.meetings:[],vs=ms.flatMap(m=>(m.presidencyVisits||[]).map(v=>({...v,sourceDate:m.sourceDate||m.date}))).filter(v=>v.date&&v.date>=today()).sort((a,b)=>String(a.date+a.time).localeCompare(String(b.date+b.time))).slice(0,5);if(!vs.length)return;const box=document.createElement('section');box.className='sv6Visits';box.innerHTML=`<div class="sv6Title"><span>Visitas da presidência</span><b>${vs.length} ${vs.length===1?'próxima visita':'próximas visitas'}</b></div>${vs.map((v,i)=>`<div class="sv6Visit"><div><b>${E(v.member||v.name||'Irmão')}</b><small>${D(v.date)}${v.time?' · '+E(v.time):''}</small></div><button data-sv6-visit="${i}">Agenda</button></div>`).join('')}`;box._visits=vs;const sec=document.querySelector('#view .section');(sec||document.getElementById('view')).insertAdjacentElement(sec?'beforebegin':'afterbegin',box)}
function peopleSummary(){if(currentTab!=='Irmãos'||document.querySelector('.sv6People'))return;const root=document.getElementById('view'),rows=[...root.querySelectorAll('.brother')];if(!rows.length)return;const box=document.createElement('div');box.className='sv6People';box.innerHTML=`<span>Quórum</span><b>${rows.length} irmãos na lista atual</b><small>Use a busca para localizar rapidamente um irmão.</small>`;const search=root.querySelector('.sbSearch');(search||root.firstElementChild)?.insertAdjacentElement(search?'afterend':'beforebegin',box)}
function download(v){const clean=s=>String(s||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;'),d=v.date.replaceAll('-',''),t=(v.time||'19:00').replace(':','')+'00',body=`BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//Quorum Vila Jacui//PT-BR\r\nCALSCALE:GREGORIAN\r\nBEGIN:VEVENT\r\nUID:${Date.now()}@vilajacui-quorum\r\nDTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'')}\r\nDTSTART:${d}T${t}\r\nSUMMARY:${clean('Visita da presidência — '+(v.member||v.name||'Irmão'))}\r\nDESCRIPTION:${clean('Quórum de Élderes · Ala Vila Jacuí')}\r\nBEGIN:VALARM\r\nTRIGGER:-PT1H\r\nACTION:DISPLAY\r\nDESCRIPTION:Lembrete da visita\r\nEND:VALARM\r\nEND:VEVENT\r\nEND:VCALENDAR`;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([body],{type:'text/calendar;charset=utf-8'}));a.download='visita-presidencia.ics';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),800)}
function run(){try{visits();peopleSummary()}catch(e){console.warn('safe bundle v6 skipped',e)}}document.addEventListener('click',e=>{const b=e.target.closest('[data-sv6-visit]');if(!b)return;const box=b.closest('.sv6Visits');download(box?._visits?.[+b.dataset.sv6Visit])});const old=window.renderTab;if(typeof old==='function')window.renderTab=function(){const r=old.apply(this,arguments);setTimeout(run,35);return r};document.addEventListener('DOMContentLoaded',()=>setTimeout(run,60));const s=document.createElement('style');s.textContent=`.sv6Visits,.sv6People{background:var(--ios-card,#fff);border-radius:16px;margin-bottom:14px;padding:16px 18px}.sv6Title span,.sv6Title b,.sv6People span,.sv6People b,.sv6People small{display:block}.sv6Title span,.sv6People span{font-size:10px;text-transform:uppercase;letter-spacing:.055em;color:var(--teal);font-weight:750}.sv6Title b,.sv6People b{font-size:16px;margin-top:3px}.sv6Visit{display:flex;justify-content:space-between;align-items:center;border-top:.5px solid var(--ios-sep,var(--line));padding:11px 0}.sv6Visit:first-of-type{margin-top:10px}.sv6Visit b,.sv6Visit small{display:block}.sv6Visit b{font-size:13px}.sv6Visit button{border:0;background:transparent;color:var(--teal);font-weight:700;padding:9px}.sv6People small{margin-top:3px}`;document.head.appendChild(s)})();